package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.lianxibu.site.repository.jobs.*;
import javax.sql.DataSource;
import java.time.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/** Actual P1 partial authority, original P2 input/retained fictional outcomes and bounded block writers. */
class SourceValuePartialArchiveTest {
    SourceValuePartialResolutionTest f;JdbcSourceValuePartialBlocks store;SourceValuePartialArchiveService service;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    void setup(boolean mixed)throws Exception{f=new SourceValuePartialResolutionTest(){@Override GenerationJdbcStoreTest database(){return SourceValuePartialArchiveTest.this.database();}};f.setup(mixed);store=new JdbcSourceValuePartialBlocks(f.db.source);service=provider(f.db.writes,f.f.f.clock);}
    SourceValuePartialArchiveService provider(SharedWriteExecutor writes,Clock clock){return new SourceValuePartialArchiveService(f.service,store,writes,new DataSourceTransactionManager(f.db.source),clock);}
    void large()throws Exception{setup(true);for(int n=0;n<f.f.plan.chunks().size();n++){f.prepare(n);f.outcomes.complete(n);}}
    int blocks(){return f.db.count("record_kind='snapshot_part' AND purpose='result' AND owner_job_id='"+f.ref.ownerId()+"'");}
    @Test void ConstructorPendingUnknownLegacyAndOuterTransactionsCannotStage()throws Exception{
        var source=mock(DataSource.class);new JdbcSourceValuePartialBlocks(source);verifyNoInteractions(source);var resolution=mock(SourceStageResolutionService.class);var blocks=mock(JdbcSourceValuePartialBlocks.class);var writes=mock(SharedWriteExecutor.class);var tx=mock(org.springframework.transaction.PlatformTransactionManager.class);new SourceValuePartialArchiveService(resolution,blocks,writes,tx,Clock.systemUTC());verifyNoInteractions(resolution,blocks,writes,tx);
        setup(true);assertNull(service.stage(f.ref));assertEquals(0,blocks());assertThrows(RuntimeException.class,()->f.original.p1.tx(()->service.stage(f.ref)));assertThrows(RuntimeException.class,()->f.original.read(()->service.stage(f.ref)));f.prepare(0);f.db.jdbc.update("UPDATE jobs SET state='unknown_external' WHERE id=?",f.f.plan.chunks().getFirst().rootId());assertNull(service.stage(f.ref));assertEquals(0,blocks());
        SourceAnalysisParentStepTest legacy=new SourceAnalysisParentStepTest(){@Override GenerationJdbcStoreTest database(){return SourceValuePartialArchiveTest.this.database();}};legacy.completedP1();legacy.step.step(legacy.candidate(legacy.handoffs.ref.ownerId()));var child=legacy.candidate(legacy.handoffs.read().p2Owner());legacy.step.step(child);var ref=legacy.reference(child.id());legacy.completeP2(ref);var reader=new SourceDedupResolvedStageResultTest();reader.f=legacy;var snapshot=reader.snapshot(ref);var original=SourceValueStageResult.createResolved(snapshot);assertEquals("source-value-stage-result-v1",com.lianxibu.site.domain.protocol.CanonicalJson.parse(original.json()).get("schema_version").asText());var known=mock(SourceStageResolutionService.class);when(known.read(ref)).thenReturn(snapshot);var closed=new SourceValuePartialArchiveService(known,new JdbcSourceValuePartialBlocks(legacy.db.source),legacy.db.writes,new DataSourceTransactionManager(legacy.db.source),legacy.clock);int count=legacy.db.count("1=1");assertNull(closed.stage(ref));assertEquals(count,legacy.db.count("1=1"));
    }
    @Test void AllAppliedValueWithPartialDedupAndZeroValueBothStageOriginalPartialBytes()throws Exception{
        large();int calls=f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class);String parent=f.db.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,f.ref.ownerId());var staged=service.stage(f.ref);assertNotNull(staged);assertFalse(staged.original().hasFailures());var original=SourceValueStageResult.createResolved(staged.original());assertTrue(blocks()>2);assertEquals(original.json(),f.original.read(()->service.verifyStaged(staged.archiveRef(),original)).json());int count=f.db.count("1=1");f.db.jdbc.execute("DROP TABLE source_run_items");f.db.jdbc.execute("DROP TABLE analyzed_entities");service=provider(f.db.writes,f.f.f.clock);assertEquals(staged.archiveRef(),service.stage(f.ref).archiveRef());assertEquals(count,f.db.count("1=1"));assertEquals(calls,f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertEquals(parent,f.db.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,f.ref.ownerId()));assertEquals(0,f.db.count("target_type='source_value_partial_result'"));
        setup(false);var zero=service.stage(f.ref);assertNotNull(zero);assertTrue(zero.original().fragments().isEmpty());assertEquals(1,zero.original().universe().accepted());assertEquals(2,blocks());assertEquals(0,f.db.count("record_kind='logical_task' AND task_type='news_value'"));assertEquals(0,f.db.count("target_type='source_value_partial_result'"));
    }
    @Test void InterruptedOriginalPrefixAndActualLostCommitAckRecoverWithoutDuplicates()throws Exception{
        large();String owner=f.ref.ownerId();f.db.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_value_block_failure CHECK(owner_job_id IS NULL OR owner_job_id<>'"+owner+"' OR purpose IS NULL OR purpose<>'result' OR part_no<>2)");assertThrows(RuntimeException.class,()->service.stage(f.ref));assertEquals(2,blocks());f.db.jdbc.execute(f.db.source instanceof org.h2.jdbcx.JdbcDataSource?"ALTER TABLE jobs DROP CONSTRAINT fictional_value_block_failure":"ALTER TABLE jobs DROP CHECK fictional_value_block_failure");service=provider(f.db.writes,f.f.f.clock);var staged=service.stage(f.ref);assertEquals(FrozenSourceValuePartial.encode(SourceValueStageResult.createResolved(staged.original())).payloads().size(),blocks());
        setup(false);var fault=new DataSourceTransactionManager(f.db.source){boolean lost;@Override protected void doCommit(org.springframework.transaction.support.DefaultTransactionStatus status){super.doCommit(status);if(!lost&&!TransactionSynchronizationManager.isCurrentTransactionReadOnly()){lost=true;throw new org.springframework.transaction.TransactionSystemException("fictional partial value ACK lost");}}};var writes=new SharedWriteExecutor(new JdbcSharedWriteEntry(f.db.source),fault,()->25,n->{});var recovered=provider(writes,f.f.f.clock).stage(f.ref);assertEquals(recovered.archiveRef(),service.stage(f.ref).archiveRef());assertEquals(2,blocks());
    }
    @Test void NativeChangeDuringStagingRejectsOldOutputAndKeepsSeparateOriginalBlocks()throws Exception{
        setup(true);for(int n=0;n<f.f.plan.chunks().size();n++){f.prepare(n);f.db.jdbc.update("UPDATE jobs SET state='failed',call_count=3,revision=revision+1 WHERE id=?",f.f.plan.chunks().get(n).rootId());}store=spy(store);doAnswer(call->{Object result=call.callRealMethod();if((int)call.getArgument(2)==0)f.db.jdbc.update("UPDATE jobs SET state='cancelled',call_count=0,revision=revision+1 WHERE id=?",f.f.plan.chunks().getFirst().rootId());return result;}).when(store).put(anyString(),anyString(),anyInt(),anyString(),any());service=provider(f.db.writes,f.f.f.clock);assertThrows(RuntimeException.class,()->service.stage(f.ref));int previous=blocks();assertTrue(previous>1);assertEquals(0,f.db.count("target_type='source_value_partial_result'"));store=new JdbcSourceValuePartialBlocks(f.db.source);service=provider(f.db.writes,f.f.f.clock);assertNotNull(service.stage(f.ref));assertTrue(blocks()>previous);assertEquals(2,f.db.jdbc.queryForObject("SELECT COUNT(DISTINCT stamp_id) FROM jobs WHERE purpose='result' AND owner_job_id=?",Integer.class,f.ref.ownerId()));
    }
    @Test void ClockDamagedBlocksHeaderAndWritableReadersFailClosed()throws Exception{
        setup(false);var premature=provider(f.db.writes,Clock.fixed(f.f.plan.scope().cutoff().minusNanos(1),ZoneOffset.UTC));assertThrows(RuntimeException.class,()->premature.stage(f.ref));assertEquals(0,blocks());var staged=service.stage(f.ref);var original=SourceValueStageResult.createResolved(staged.original());assertThrows(RuntimeException.class,()->service.verifyStaged(staged.archiveRef(),original));assertThrows(RuntimeException.class,()->f.original.p1.tx(()->service.verifyStaged(staged.archiveRef(),original)));assertSame(original,f.original.read(()->service.verifyStaged(staged.archiveRef(),original)));f.db.jdbc.update("UPDATE jobs SET payload_hash=? WHERE purpose='result' AND owner_job_id=? AND part_no=1",new byte[32],f.ref.ownerId());assertThrows(RuntimeException.class,()->service.stage(f.ref));assertThrows(RuntimeException.class,()->f.original.read(()->service.verifyStaged(staged.archiveRef(),original)));assertEquals(2,blocks());f.db.jdbc.update("UPDATE jobs SET task_type='news_dedup' WHERE id=?",f.ref.ownerId());assertThrows(RuntimeException.class,()->f.original.read(()->{store.immutableOwner(f.ref.ownerId());return true;}));assertThrows(RuntimeException.class,()->f.original.p1.tx(()->{store.lockOwner(f.ref.ownerId());return true;}));
    }
}
